601		// 过期请求不能通过重复申请重新创建（会话仍有效，应返回过期视图）。
602		if req, err := w.Apply(in); err != nil || req.State != RequestExpired {
603			t.Fatalf("re-apply expired: view=%+v err=%v", req, err)
604		}
605	}
