900	// validateSubmissionTiming 校验请求记载的提交时刻必须是正常申请能够产生的
901	// 历史：正常提交时，策略尚未开始、已经结束或申请会话已经到期的申请都会被
902	// 拒绝（只留下不关联请求的拒绝账本记录），不可能进入已受理请求序列。因此
903	// 备份中每笔已受理请求的提交时刻必须：
904	//   - 不早于关联策略的开始时刻（恰在策略开始时提交可以接受）；
905	//   - 严格早于策略结束时刻（恰在策略结束时提交必须拒绝）；
906	//   - 严格早于申请会话的到期时刻（恰在会话到期时提交必须拒绝）。
907	//
908	// 直接预留与经过审批的申请适用同一规则；后来已经结算、取消、拒绝或过期
909	// （含预留超时）的请求也不豁免。时间一律按保存的完整时刻以 time.Time 的
910	// 绝对瞬间比较（Before）：纳秒精度保留，不同时区表示的同一时刻判定相同。
911	// 该校验只针对备份记载的提交历史，与恢复时的当前时间无关：申请当时符合
912	// 条件、之后会话到期或被吊销、策略结束或被停用的请求仍按现有规则恢复。
913	func validateSubmissionTiming(r *request, p *policy, sess *session) error {
914		if r.createdAt.Before(p.startsAt) {
915			return fmt.Errorf("created_at %v is before policy %q window starts_at %v", r.createdAt, p.id, p.startsAt)
916		}
917		if !r.createdAt.Before(p.endsAt) {
918			return fmt.Errorf("created_at %v is not strictly before policy %q window ends_at %v", r.createdAt, p.id, p.endsAt)
919		}
920		if !r.createdAt.Before(sess.expiresAt) {
921			return fmt.Errorf("created_at %v is not strictly before session %q expiry %v", r.createdAt, sess.id, sess.expiresAt)
922		}
923		return nil
924	}
925	
926	// validateDeactivationTiming 校验关联已停用策略的请求，其时间线必须是正常
927	// 流程能够产生的历史：策略首次停用后不再受理新申请、也不再批准待审批请求
928	// （停用瞬间未到等待期限的待审批请求立即被拒绝，已到期限的进入过期终态），
929	// 因此备份中关联已停用策略的每笔已受理请求：
930	//   - 提交时刻不得严格晚于策略的首次停用时刻（停用后才提交的申请只会留下
931	//     不关联请求的拒绝账本记录，不可能成为已受理请求）；
932	//   - 超过审批门槛、经批准才预留费用的请求，其批准时刻同样不得严格晚于
933	//     首次停用时刻（停用后出资账户已无法再批准）。直接受理的请求不携带
934	//     审批信息，不适用批准时刻核对。
935	//
936	// 两项核对对请求后来的状态一律适用：已结算、已取消、被拒绝、待审批过期或
937	// 预留超时的历史也不豁免——后续处理时刻不是新的提交或批准时刻。提交或批准
938	// 与首次停用时刻完全相同时可以接受：先完成申请或批准、再停用，二者可能共享
939	// 同一个时间戳，只有严格更晚才矛盾。时间一律按保存的完整时刻以 time.Time
940	// 的绝对瞬间比较（After）：纳秒精度保留，不同时区表示的同一时刻判定相同。
941	// 仍处于待审批状态的请求不适用提交时刻核对：它们已被“已停用策略不得保留
942	// 待审批请求”的专项核对覆盖，由该核对给出对应的矛盾说明。
943	// 该校验只针对备份记载的历史时刻，与恢复时的当前时间无关：不能先把相关预留
944	// 按当前时间退回，再接受本不合法的备份。未停用策略下的请求不受此限。
945	func validateDeactivationTiming(r *request, p *policy, approvalRequired bool) error {
946		if !p.deactivated {
947			return nil
948		}
949		if r.state != RequestPendingApproval && r.createdAt.After(p.deactivatedAt) {
950			return fmt.Errorf("usage account %q request %q was submitted at %v, after policy %q was first deactivated at %v: a deactivated policy cannot accept new submissions",
951				r.accountID, r.requestID, r.createdAt, p.id, p.deactivatedAt)
952		}
953		if approvalRequired && !r.reservedAt.IsZero() && r.decidedAt.After(p.deactivatedAt) {
954			return fmt.Errorf("usage account %q request %q was approved at %v, after policy %q was first deactivated at %v: a deactivated policy cannot approve requests",
955				r.accountID, r.requestID, r.decidedAt, p.id, p.deactivatedAt)
956		}
957		return nil
958	}
959	
960	// validateRequestTimingAndState 校验请求状态与其计时/金额字段自洽，并与
961	// 不可变的策略条件、申请会话保持一致，防止任意状态搭配任意时间戳的损坏
962	// 备份。sess 为该请求的申请会话。
963	func validateRequestTimingAndState(r *request, p *policy, sess *session) error {
964		if r.createdAt.IsZero() {
965			return errors.New("request missing created_at")
966		}
967		// 提交时刻必须是正常申请能够产生的历史：落在策略时间窗内且申请会话
968		// 尚未到期。对直接预留与经过审批的申请、以及所有后续状态统一适用。
969		if err := validateSubmissionTiming(r, p, sess); err != nil {
970			return err
971		}
972		if r.operation == "" || r.payee == "" {
973			return errors.New("operation and payee are required")
974		}
975		if r.operation != p.operation || r.payee != p.payee {
976			return fmt.Errorf("operation/payee do not match policy %q", p.id)
977		}
978		if r.estimatedFee > p.maxPerRequest {
979			return fmt.Errorf("estimated fee %d exceeds policy per-request limit %d", r.estimatedFee, p.maxPerRequest)
980		}
981		if r.approverAccountID != "" && r.approverAccountID != r.payerAccountID {
982			return fmt.Errorf("approver account %q is not the payer %q", r.approverAccountID, r.payerAccountID)
983		}
984		if r.actualFee > r.estimatedFee {
985			return fmt.Errorf("actual fee %d exceeds estimated fee %d", r.actualFee, r.estimatedFee)
986		}
987	
988		// 申请是否必须走过审批由不可变策略门槛决定：费用严格超过正门槛的请求
989		// 只能来自待审批流程；其余请求只能直接预留。
990		approvalRequired := p.approvalThreshold > 0 && r.estimatedFee > p.approvalThreshold
991		reservedOrigin := !r.reservedAt.IsZero()
992	
993		// 已停用策略下的请求，其提交（及经审批请求的批准）不得严格晚于策略的
994		// 首次停用时刻；对全部后续状态统一适用。
995		if err := validateDeactivationTiming(r, p, approvalRequired); err != nil {
996			return err
997		}
998	
999		switch r.state {
1000		case RequestReserved, RequestSettled, RequestReservationExpired:
1001			// 这三类一定发生过预留。
1002			if err := validateReservedOrigin(r, p, sess, approvalRequired, reservedOrigin); err != nil {
1003				return err
1004			}
1005		case RequestPendingApproval, RequestRejected, RequestExpired:
1006			// 这三类一定从未预留，且必须来自开启审批的策略。
1007			if err := validatePendingOrigin(r, p, approvalRequired, reservedOrigin); err != nil {
1008				return err
1009			}
1010		case RequestCancelled:
1011			// 取消可能来自待审批（从未预留）或已预留。
1012			if reservedOrigin {
1013				if err := validateReservedOrigin(r, p, sess, approvalRequired, true); err != nil {
1014					return err
1015				}
1016			} else {
1017				if err := validatePendingOrigin(r, p, approvalRequired, false); err != nil {
1018					return err
1019				}
1020			}
1021		default:
1022			return fmt.Errorf("unknown state %d", r.state)
1023		}
1024	
1025		switch r.state {
1026		case RequestReserved:
1027			// 启用超时时 deadline 必须等于 reservedAt + 时长，未启用时为零，
1028			// 且不得已记录超时。
1029			if err := validateReserveTiming(r); err != nil {
1030				return err
1031			}
1032			if !r.reserveExpiredAt.IsZero() {
1033				return errors.New("reserved request must not carry reserve-expired time")
1034			}
1035			if r.actualFee != 0 || !r.settledAt.IsZero() {
1036				return errors.New("reserved request must not be settled")
1037			}
1038			if r.rejectReason != "" {
1039				return errors.New("reserved request must not carry a reject reason")
1040			}
1041		case RequestSettled:
1042			if r.settledAt.IsZero() {
1043				return errors.New("settled request missing settled_at")
1044			}
1045			if !r.reserveExpiredAt.IsZero() {
1046				return errors.New("settled request must not carry reserve-expired time")
1047			}
1048			if err := validateReserveTiming(r); err != nil {
1049				return err
1050			}
1051			// 结算时刻必须落在有效预留期内：启用预留超时时严格早于截止时刻。
1052			if err := validateSettlementTiming(r); err != nil {
1053				return err
1054			}
1055			if r.rejectReason != "" {
1056				return errors.New("settled request must not carry a reject reason")
1057			}
1058		case RequestCancelled:
1059			if r.actualFee != 0 || !r.settledAt.IsZero() {
1060				return errors.New("cancelled request must not be settled")
1061			}
1062			if !r.reserveExpiredAt.IsZero() {
1063				return errors.New("cancelled request must not carry reserve-expired time")
1064			}
1065			if r.rejectReason != "" {
1066				return errors.New("cancelled request must not carry a reject reason")
1067			}
1068			if reservedOrigin {
1069				if err := validateReserveTiming(r); err != nil {
1070					return err
1071				}
1072			} else {
1073				// 待审批取消：决定时间必填，且等待期限与取消决定时刻必须是
1074				// 正常取消能够产生的历史。
1075				if r.decidedAt.IsZero() {
1076					return errors.New("cancelled-from-pending request missing decided_at")
1077				}
1078				if err := validateWaitDeadline(r, p, sess, "cancelled-from-pending request"); err != nil {
1079					return err
1080				}
1081				if err := validateWaitDecisionTiming(r, "cancellation"); err != nil {
1082					return err
1083				}
1084			}
1085		case RequestPendingApproval:
1086			// 待审批不冻结余额：不得有实际费用，且等待期限必须等于
1087			// min(提交+等待时长, 策略结束, 申请会话到期)。
1088			if r.actualFee != 0 || !r.settledAt.IsZero() {
1089				return errors.New("pending request must not be settled")
1090			}
1091			if r.waitDeadline.IsZero() {
1092				return errors.New("pending request missing wait deadline")
1093			}
1094			if r.approverAccountID != "" {
1095				return errors.New("pending request must not carry an approver")
1096			}
1097			if r.rejectReason != "" {
1098				return errors.New("pending request must not carry a reject reason")
1099			}
1100			// 已停用策略下不得残留待审批请求：正常停用时，未到等待期限的待审批
1101			// 请求会立即随停用进入拒绝终态，已到（含恰到）或超过期限的进入过期
1102			// 终态，二者皆终态、不再等待批准。备份保存的“已停用策略 + 待审批
1103			// 请求”是正常流程不可能产生的矛盾状态，必须整体拒绝。该校验只看备份
1104			// 保存的状态，与恢复时的当前时间无关：等待期限尚未到达、恰好到达或
1105			// 早已过去结果相同；不能先在恢复时把该请求自动过期、再把矛盾备份当作
1106			// 合法数据，也不替调用方补写停用拒绝记录、清除停用标志或改写请求。
1107			// 停用前已进入其他状态（已预留、已结算、已取消、被拒绝、已过期、预留
1108			// 超时）的历史请求不受此限，已停用策略本身及其全部合法历史仍可恢复。
1109			if p.deactivated {
1110				return fmt.Errorf("usage account %q request %q is still pending approval under deactivated policy %q: a deactivated policy cannot retain pending-approval requests", r.accountID, r.requestID, p.id)
1111			}
1112			// 已吊销申请会话下不得残留待审批请求：主动吊销会话时，未到等待期限的
1113			// 待审批请求会立即随吊销进入拒绝终态，已到（含恰到）或超过期限的进入
1114			// 过期终态，二者皆终态、不再等待批准。备份保存的“申请会话已吊销 +
1115			// 待审批请求”是正常流程不可能产生的矛盾状态，必须整体拒绝。该校验只看
1116			// 备份保存的吊销标记与请求状态，与恢复时的当前时间无关：等待期限尚未
1117			// 到达、恰好到达或早已过去结果相同；不能先在恢复时把该请求按当前时间
1118			// 自动过期、再把矛盾备份当作合法数据，也不替调用方补写吊销拒绝决定、
1119			// 猜测吊销时间、清除吊销标记或删除请求来消除矛盾。这里按提交申请所用的
1120			// 会话判断：即使出资账户用于审批的会话仍然有效，也不能让矛盾备份恢复
1121			// 成功。吊销前已进入其他状态（已预留、已结算、已取消、被拒绝、已过期、
1122			// 预留超时）的历史请求不受此限，已吊销会话本身及其全部合法历史仍可恢复。
1123			if sess.revoked {
1124				return fmt.Errorf("usage account %q request %q is still pending approval under revoked application session %q: a revoked session cannot retain pending-approval requests", r.accountID, r.requestID, sess.id)
1125			}
1126			// 待审批没有决定时刻，只需核对保存的等待截止时刻。
1127			if err := validateWaitDeadline(r, p, sess, "pending request"); err != nil {
1128				return err
1129			}
1130		case RequestRejected:
1131			if r.decidedAt.IsZero() || r.rejectReason == "" {
1132				return errors.New("rejected request missing decided_at or reason")
1133			}
1134			// 等待截止时刻与拒绝决定时刻必须是正常审批流程能够产生的历史：
1135			// 出资账户主动拒绝、申请会话吊销、策略停用三条路径统一适用。
1136			if err := validateWaitDeadline(r, p, sess, "rejected request"); err != nil {
1137				return err
1138			}
1139			if err := validateWaitDecisionTiming(r, "rejection"); err != nil {
1140				return err
1141			}
1142		case RequestExpired:
1143			if r.decidedAt.IsZero() {
1144				return errors.New("expired request missing decided_at")
1145			}
1146			if r.rejectReason != "" {
1147				return errors.New("expired request must not carry a reject reason")
1148			}
1149			// 等待截止时刻与过期决定时刻必须是正常到期处理能够产生的历史：
1150			// 截止时刻必须等于提交时确定的期限，决定不得早于该截止时刻。
1151			if err := validateExpirationTiming(r, p, sess); err != nil {
1152				return err
1153			}
1154		case RequestReservationExpired:
1155			if r.reserveDuration <= 0 {
1156				return errors.New("reservation-expired request must have a positive reserve duration")
1157			}
1158			if err := validateReserveTiming(r); err != nil {
1159				return err
1160			}
1161			if !r.reserveExpiredAt.Equal(r.reserveDeadline) {
1162				return errors.New("reserve-expired-at must equal reserve deadline")
1163			}
1164			if r.actualFee != 0 || !r.settledAt.IsZero() {
1165				return errors.New("reservation-expired request must not be settled")
1166			}
1167			if r.rejectReason != "" {
1168				return errors.New("reservation-expired request must not carry a reject reason")
1169			}
1170		}
1171		return nil
1172	}
1173	
1174	// expectedWaitDeadline 计算审批路径请求的等待截止时刻：提交时刻 + 策略
1175	// 等待时长、策略结束时间、申请会话到期时间三者中的最早值。所有走过审批
1176	// 流程的请求（待审批、批准、拒绝、待审批取消、待审批过期）保存的等待
1177	// 截止时刻都必须与该值一致。
1178	func expectedWaitDeadline(r *request, p *policy, sess *session) time.Time {
1179		want := r.createdAt.Add(p.approvalWait)
1180		if p.endsAt.Before(want) {
1181			want = p.endsAt
1182		}
1183		if sess.expiresAt.Before(want) {
1184			want = sess.expiresAt
1185		}
1186		return want
1187	}
1188	
1189	// validateWaitDeadline 核对审批路径请求保存的等待截止时刻自洽：不得缺失，
1190	// 且必须等于提交时刻+策略等待时长、策略结束时间、申请会话到期时间三者的
1191	// 最早值；提前或推迟都拒绝，即使决定时刻仍落在修改后的期限内。
1192	//
1193	// whatNoun 为请求所处的审批环节名称（如 "approved request"、"rejected
1194	// request"、"cancelled-from-pending request"、"expired request"），用于保留
1195	// 各环节原有的错误措辞。待审批、批准、拒绝、待审批取消与待审批过期共用这
1196	// 同一条业务规则，不再分别维护。
1197	//
1198	// 时间一律按保存的完整时刻以 time.Time 的绝对瞬间比较（Equal）：纳秒精度
1199	// 保留，不同时区表示的同一时刻判定相同。该校验只针对备份记载的历史时刻，
1200	// 与恢复时的当前时间无关。
1201	func validateWaitDeadline(r *request, p *policy, sess *session, whatNoun string) error {
1202		if r.waitDeadline.IsZero() {
1203			return fmt.Errorf("%s missing wait deadline", whatNoun)
1204		}
1205		if want := expectedWaitDeadline(r, p, sess); !r.waitDeadline.Equal(want) {
1206			return fmt.Errorf("wait deadline %v does not match min(created+wait, policy end, session expiry) %v", r.waitDeadline, want)
1207		}
1208		return nil
1209	}
1210	
1211	// validateWaitDecisionTiming 核对“期限内决定”（批准、拒绝、待审批取消）
1212	// 共用的决定时刻规则：决定必须不早于提交时刻（恰在提交时刻决定可以接受），
1213	// 且严格早于等待截止时刻——决定早于提交、恰到截止时刻或晚于截止时刻都不
1214	// 可能在正常审批流程中产生（截止时刻及之后请求只能进入待审批过期终态）。
1215	//
1216	// actionNoun 为操作名称（"approval"、"rejection"、"cancellation"），用于保留
1217	// 各操作原有的错误措辞。调用方须先通过 validateWaitDeadline 确认截止时刻
1218	// 存在且正确，本函数不再重复该核对。时间一律按保存的完整时刻以 time.Time
1219	// 的绝对瞬间比较（Before）：纳秒精度保留，不同时区表示的同一时刻判定相同。
1220	// 该校验只针对备份记载的提交与决定历史，与恢复时的当前时间无关：期限内的
1221	// 合法决定即使很久以后恢复、申请会话已到期或吊销、策略已结束或停用，仍保持
1222	// 原状态、金额、决定信息与账本顺序，不追加退款或过期记录。
1223	func validateWaitDecisionTiming(r *request, actionNoun string) error {
1224		if r.decidedAt.Before(r.createdAt) {
1225			return fmt.Errorf("%s decided_at %v is before created_at %v", actionNoun, r.decidedAt, r.createdAt)
1226		}
1227		if !r.decidedAt.Before(r.waitDeadline) {
1228			return fmt.Errorf("%s decided_at %v is not strictly before wait deadline %v", actionNoun, r.decidedAt, r.waitDeadline)
1229		}
1230		return nil
1231	}
1232	
1233	// validateExpirationTiming 校验“待审批过期”（从未预留费用、因等待审批到期
1234	// 进入已过期终态）的请求保存的等待期限与过期决定时刻自洽，防止备份中出现
1235	// 正常流程不可能产生的过期历史：
1236	//   - 等待截止时刻核对与批准、拒绝、待审批取消共用同一规则（见
1237	//     validateWaitDeadline）：缺失、提前、推迟都拒绝，即使修改后的截止时刻
1238	//     仍早于记载的过期决定；策略结束或会话到期更早时按最早的那个时刻判断，
1239	//     不能只按最长等待时长；

