			return PolicySpec{
				ID: id, PayerAccountID: "payer", AllowedAccountIDs: []string{"u1"},
				Operation: "charge", Payee: "shop",
				StartsAt: t0.Add(-time.Hour), EndsAt: t0.Add(time.Hour),
				MaxPerRequest: 100, MaxTotal: 1000,
