const sessionRevokedRejectReason = "application session revoked before approval"

// policyDeactivatedRejectReason 生成策略在等待期限内被停用时请求的拒绝原因：
// 说明策略被停用并包含停用理由（停用理由在 DeactivatePolicy 入口已按去掉
