package wallet

import "testing"

func TestZZRefactorWhitespaceReasonPreserved(t *testing.T) {
	w, _ := setupApproval(t)
	if _, err := w.Apply(approvalApply()); err != nil {
		t.Fatal(err)
	}
	raw := "  keep spaces  "
	r, err := w.Reject("u1", "r1", "sa", "dev-approve", raw)
	if err != nil {
		t.Fatal(err)
	}
	if r.RejectReason != raw {
		t.Fatalf("request reason = %q, want raw %q", r.RejectReason, raw)
	}
	e, ok := ledgerEntryFor(w.Ledger(), LedgerRejection, "r1")
	if !ok || e.Reason != raw || e.AccountID != "u1" || e.Amount != 0 {
		t.Fatalf("ledger entry = %+v ok=%v", e, ok)
	}
	if r.ApproverAccountID != "payer" {
		t.Fatalf("approver = %q", r.ApproverAccountID)
	}
	// 相同原文（含空白）幂等；去空白后的不同文本视为冲突。
	if _, err := w.Reject("u1", "r1", "sa", "dev-approve", raw); err != nil {
		t.Fatalf("idempotent raw repeat: %v", err)
	}
	if _, err := w.Reject("u1", "r1", "sa", "dev-approve", "keep spaces"); !errorIs(err, ErrConflict) {
		t.Fatalf("trimmed variant err = %v, want ErrConflict", err)
	}
}
EOF
cat >> wallet/zz_refactor_check_test.go <<'EOF'

func errorIs(err error, target error) bool {
	if err == nil {
		return false
	}
	return err.Error() == target.Error() || (err != nil && target != nil && err.Error() != "" && containsErr(err, target))
}
func containsErr(err, target error) bool {
	type wrap interface{ Unwrap() error }
	for err != nil {
		if err == target {
			return true
		}
		u, ok := err.(wrap)
		if !ok {
			return false
		}
		err = u.Unwrap()
	}
	return false
}
EOF
